import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";

export default function PostAttributesPage() {
  const { category } = useParams();

  // Form State
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    price: "",
    category: category,
    location: "",
    brand: "",
    paymentOptions: [],
    name: "lawal muazu",
    phoneNumber: "",
    contactMethod: [],
  });

  // Update category when URL parameter changes
  useEffect(() => {
    setFormData((prevData) => ({ ...prevData, category: category }));
  }, [category]);

  // Handle input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  // Handle checkbox changes
  const handleCheckboxChange = (e) => {
    const { name, checked } = e.target;
    setFormData((prevData) => {
      const updatedOptions = checked
        ? [...prevData[name], e.target.value]
        : prevData[name].filter((option) => option !== e.target.value);
      return { ...prevData, [name]: updatedOptions };
    });
  };

  // Form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Form submitted successfully!");
    console.log(formData); // For debugging
  };

  return (
    <div className="container mx-auto px-4 py-6">
      {/* Header Section */}
      <div className="mb-6 text-center">
        <h1 className="text-3xl font-semibold text-gray-800">Post Your Ad</h1>
        <p className="text-gray-600 mt-2">Fill in the details to post your ad.</p>
      </div>

      {/* Form Section */}
      <form
        onSubmit={handleSubmit}
        className="bg-white shadow-md rounded-md p-6 space-y-4 max-w-2xl mx-auto"
      >
        {/* Category */}
        <div>
          <label htmlFor="category" className="block text-gray-700">Category</label>
          <input
            type="text"
            id="category"
            name="category"
            value={formData.category}
            readOnly
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm bg-gray-100 cursor-not-allowed"
          />
        </div>

        {/* Brand */}
        <div>
          <label htmlFor="brand" className="block text-gray-700">Brand*</label>
          <select
            id="brand"
            name="brand"
            value={formData.brand}
            onChange={handleInputChange}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm"
          >
            <option value="">Select brand</option>
            {/* Add brand options here */}
          </select>
        </div>

        {/* Ad Title */}
        <div>
          <label htmlFor="title" className="block text-gray-700">Ad title*</label>
          <input
            type="text"
            id="title"
            name="title"
            value={formData.title}
            onChange={handleInputChange}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm"
            placeholder="Mention the key features of your item (e.g. brand, model, age, type)"
          />
        </div>

        {/* Description */}
        <div>
          <label htmlFor="description" className="block text-gray-700">Description*</label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleInputChange}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm"
            placeholder="Describe the item you’re selling. Include condition, features and reason for selling"
          />
        </div>

        {/* Location */}
        <div>
          <label htmlFor="location" className="block text-gray-700">Location*</label>
          <input
            type="text"
            id="location"
            name="location"
            value={formData.location}
            onChange={handleInputChange}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm"
            placeholder="Select Location"
          />
        </div>

        {/* Payment Options */}
        <div>
          <label className="block text-gray-700">Payment Options</label>
          <div className="mt-1 space-y-2">
            {["Cash", "Exchange", "Installments", "Cash or Installment"].map((option) => (
              <div key={option} className="flex items-center">
                <input
                  type="checkbox"
                  id={option}
                  name="paymentOptions"
                  value={option}
                  checked={formData.paymentOptions.includes(option)}
                  onChange={handleCheckboxChange}
                  className="h-4 w-4 text-blue-600 border-gray-300 rounded"
                />
                <label htmlFor={option} className="ml-2 block text-gray-700">{option}</label>
              </div>
            ))}
          </div>
        </div>

        {/* Price */}
        <div>
          <label htmlFor="price" className="block text-gray-700">Price*</label>
          <input
            type="text"
            id="price"
            name="price"
            value={formData.price}
            onChange={handleInputChange}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm"
            placeholder="Enter Price"
          />
        </div>

        {/* Name */}
        <div>
          <label htmlFor="name" className="block text-gray-700">Name*</label>
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            readOnly
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm bg-gray-100 cursor-not-allowed"
          />
        </div>

        {/* Mobile Phone Number */}
        <div>
          <label htmlFor="phoneNumber" className="block text-gray-700">Mobile Phone Number*</label>
          <div className="flex">
            <span className="inline-flex items-center px-3 rounded-l-md border border-r-0 border-gray-300 bg-gray-50 text-gray-500 text-sm">+20</span>
            <input
              type="text"
              id="phoneNumber"
              name="phoneNumber"
              value={formData.phoneNumber}
              onChange={handleInputChange}
              className="mt-1 block w-full border-gray-300 rounded-r-md shadow-sm"
              placeholder="Enter phone number"
            />
          </div>
        </div>

        {/* Contact Method */}
        <div>
          <label className="block text-gray-700">Contact Method</label>
          <div className="mt-1 space-y-2">
            {["Phone Number", "Dubizzle Chat", "Both"].map((method) => (
              <div key={method} className="flex items-center">
                <input
                  type="checkbox"
                  id={method}
                  name="contactMethod"
                  value={method}
                  checked={formData.contactMethod.includes(method)}
                  onChange={handleCheckboxChange}
                  className="h-4 w-4 text-blue-600 border-gray-300 rounded"
                />
                <label htmlFor={method} className="ml-2 block text-gray-700">{method}</label>
              </div>
            ))}
          </div>
        </div>

        {/* Submit Button */}
        <div>
          <button
            type="submit"
            className="w-full bg-blue-500 text-white py-2 px-4 rounded-md shadow-sm hover:bg-blue-600"
          >
            Post now
          </button>
        </div>
      </form>
    </div>
  );
}
